-- 02: Load reproducible fictional sample data (generated by data/generate_sample_data.py, seed 42)
-- All names, email addresses and transactions are synthetic. Safe to re-run: tables are emptied first.
BEGIN;
SET LOCAL search_path TO retail, public;
TRUNCATE order_items, orders, products, categories, customers RESTART IDENTITY CASCADE;






-- Re-sync identity sequences because explicit IDs were inserted.
DO $$ BEGIN
    PERFORM setval(pg_get_serial_sequence('retail.categories', 'category_id'), (SELECT MAX(category_id) FROM categories));
    PERFORM setval(pg_get_serial_sequence('retail.customers', 'customer_id'), (SELECT MAX(customer_id) FROM customers));
    PERFORM setval(pg_get_serial_sequence('retail.products', 'product_id'), (SELECT MAX(product_id) FROM products));
    PERFORM setval(pg_get_serial_sequence('retail.orders', 'order_id'), (SELECT MAX(order_id) FROM orders));
    PERFORM setval(pg_get_serial_sequence('retail.order_items', 'order_item_id'), (SELECT MAX(order_item_id) FROM order_items));
END $$;

COMMIT;

-- Load validation
SELECT 'categories' AS table_name, COUNT(*) AS row_count FROM retail.categories
UNION ALL SELECT 'customers', COUNT(*) FROM retail.customers
UNION ALL SELECT 'products', COUNT(*) FROM retail.products
UNION ALL SELECT 'orders', COUNT(*) FROM retail.orders
UNION ALL SELECT 'order_items', COUNT(*) FROM retail.order_items
ORDER BY table_name;

